const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { EventEmitter } = require('events');

class UploadProcessor extends EventEmitter {
  constructor(config) {
    super();
    this.uploadDir = config.uploadDir || '/tmp/uploads';
    this.maxSize = config.maxSize || 50 * 1024 * 1024;
    this.processingState = new Map();
    this.shutdownRequested = false;
    this.activeUploads = 0;
    this._setupSignalHandlers();
  }

  _setupSignalHandlers() {
    const gracefulShutdown = (signal) => {
      console.log(`Received ${signal}, initiating graceful shutdown`);
      this.shutdownRequested = true;
      this._drainAndExit();
    };
    process.on('SIGTERM', gracefulShutdown);
    process.on('SIGINT', gracefulShutdown);
  }

  async _drainAndExit() {
    if (this.activeUploads > 0) {
      console.log(`Waiting for ${this.activeUploads} active uploads...`);
      await this._waitForDrain();
    }
    await this._cleanupTempFiles();
    process.exit(0);
  }

  async _waitForDrain() {
    return new Promise((resolve) => {
      const check = () => {
        if (this.activeUploads <= 0) resolve();
        else setTimeout(check, 100);
      };
      check();
    });
  }

  async _cleanupTempFiles() {
    for (const [uploadId, state] of this.processingState.entries()) {
      if (state.status === 'receiving') {
        const filePath = state.tempPath;
        try {
          if (fs.existsSync(filePath)) {
            fs.unlinkSync(filePath);
          }
        } catch (e) {
          console.error(`Cleanup failed for ${uploadId}: ${e.message}`);
        }
      }
    }
  }

  _validateUploadId(uploadId) {
    // Prevent path traversal: uploadId is used in filesystem paths.
    if (typeof uploadId !== 'string' || uploadId.length === 0 || uploadId.length > 128) {
      throw new Error('Invalid uploadId');
    }
    if (!/^[a-zA-Z0-9_-]+$/.test(uploadId)) {
      throw new Error('Invalid uploadId: contains disallowed characters');
    }
    return uploadId;
  }

  async processUpload(uploadId, stream, metadata) {
    if (this.shutdownRequested) {
      throw new Error('Server shutting down, rejecting upload');
    }

    this._validateUploadId(uploadId);

    this.activeUploads++;
    const tempPath = path.join(this.uploadDir, `${uploadId}.tmp`);

    this.processingState.set(uploadId, {
      status: 'receiving',
      tempPath: tempPath,
      metadata: metadata,
      startTime: Date.now()
    });

    try {
      await this._receiveFile(uploadId, stream, tempPath);
      await this._validateFile(uploadId, tempPath, metadata);
      const finalPath = await this._finalizeUpload(uploadId, tempPath, metadata);
      return { success: true, path: finalPath, uploadId };
    } catch (err) {
      await this._rollback(uploadId, tempPath);
      throw err;
    } finally {
      this.activeUploads--;
    }
  }

  async _receiveFile(uploadId, stream, tempPath) {
    return new Promise((resolve, reject) => {
      let bytesWritten = 0;
      const writeStream = fs.createWriteStream(tempPath);

      stream.on('data', (chunk) => {
        bytesWritten += chunk.length;
        if (bytesWritten > this.maxSize) {
          writeStream.destroy();
          reject(new Error(`Upload ${uploadId} exceeds max size`));
          return;
        }
        writeStream.write(chunk);
      });

      stream.on('end', () => {
        writeStream.end(() => resolve());
      });

      stream.on('error', (err) => {
        writeStream.destroy();
        reject(err);
      });
    });
  }

  async _validateFile(uploadId, tempPath, metadata) {
    const state = this.processingState.get(uploadId);
    state.status = 'validating';

    const fileBuffer = fs.readFileSync(tempPath);
    const hash = crypto.createHash('sha256').update(fileBuffer).digest('hex');

    if (metadata.expectedHash && metadata.expectedHash !== hash) {
      throw new Error(`Hash mismatch for ${uploadId}`);
    }

    const contentType = this._detectContentType(fileBuffer);
    if (!this._isAllowedContentType(contentType, metadata.allowedTypes)) {
      throw new Error(`Disallowed content type: ${contentType}`);
    }

    state.status = 'validated';
    state.hash = hash;
    state.contentType = contentType;
  }

  async _finalizeUpload(uploadId, tempPath, metadata) {
    const state = this.processingState.get(uploadId);

    const sanitizedName = this._sanitizeFilename(metadata.originalName || 'unnamed');
    const finalDir = path.join(this.uploadDir, 'finalized');
    const finalPath = path.join(finalDir, `${uploadId}_${sanitizedName}`);

    if (!fs.existsSync(finalDir)) {
      fs.mkdirSync(finalDir, { recursive: true });
    }

    // Atomically rename - if file was already cleaned up, this throws
    // and the error is caught by the caller
    fs.renameSync(tempPath, finalPath);
    state.status = 'finalized';
    state.finalPath = finalPath;
    this.processingState.delete(uploadId);

    return finalPath;
  }

  _sanitizeFilename(name) {
    return name.replace(/[^a-zA-Z0-9._-]/g, '_').substring(0, 128);
  }

  _detectContentType(buffer) {
    if (buffer[0] === 0xFF && buffer[1] === 0xD8) return 'image/jpeg';
    if (buffer[0] === 0x89 && buffer[1] === 0x50) return 'image/png';
    if (buffer[0] === 0x25 && buffer[1] === 0x50) return 'application/pdf';
    return 'application/octet-stream';
  }

  _isAllowedContentType(detected, allowedTypes) {
    if (!allowedTypes || allowedTypes.length === 0) return true;
    return allowedTypes.includes(detected);
  }

  async _rollback(uploadId, tempPath) {
    try {
      if (fs.existsSync(tempPath)) {
        fs.unlinkSync(tempPath);
      }
    } catch (e) { /* best effort */ }
    this.processingState.delete(uploadId);
  }
}

module.exports = { UploadProcessor };
